// e2e/helpers/NavigationHelper.ts
// Generated by e2e-flow skill (Phase 1). Maps to Tabs/Breadcrumb/routing.
import { expect } from "@playwright/test"
import type { Locator, Page } from "@playwright/test"

export class NavigationHelper {
  constructor(private readonly page: Page) {}

  /** 탭 클릭. */
  async clickTab(
    tabName: string | RegExp,
    opts?: { within?: Locator }
  ): Promise<void> {
    const root = opts?.within ?? this.page
    await root.getByRole("tab", { name: tabName }).click()
  }

  /** URL이 패턴과 매칭되는지 검증. page 전역 상태라 within 옵션 없음. */
  async expectUrlMatches(pattern: string | RegExp): Promise<void> {
    await expect(this.page).toHaveURL(pattern)
  }

  /** 현재 활성 탭 검증. */
  async expectActiveTab(
    tabName: string | RegExp,
    opts?: { within?: Locator }
  ): Promise<void> {
    const root = opts?.within ?? this.page
    await expect(
      root.getByRole("tab", { name: tabName, selected: true })
    ).toBeVisible()
  }

  /** 브레드크럼 항목 순서대로 검증. */
  async expectBreadcrumb(
    items: Array<string>,
    opts?: { within?: Locator }
  ): Promise<void> {
    const root = opts?.within ?? this.page
    const breadcrumb = root.getByRole("navigation", {
      name: /breadcrumb|경로/i,
    })
    for (const item of items) {
      await expect(breadcrumb.getByText(item)).toBeVisible()
    }
  }

  /** 페이지 메인 영역(role=main)이 보이는지 검증. */
  async expectMainVisible(opts?: { within?: Locator }): Promise<void> {
    const root = opts?.within ?? this.page
    await expect(root.getByRole("main")).toBeVisible()
  }

  // ── Added for this repo (not in the e2e-flow template) ──────────────────

  /**
   * 쿼리 파라미터 하나를 검증한다. `null` 이면 그 파라미터가 없어야 한다.
   * 필터·탭이 `replace` 내비게이션으로 URL 을 바꾸고 검색은 디바운스되므로 폴링한다.
   */
  async expectSearchParam(key: string, value: string | null): Promise<void> {
    await expect
      .poll(() => new URL(this.page.url()).searchParams.get(key))
      .toBe(value)
  }

  /** 탭에 딸린 패널(role=tabpanel, 이름 = 탭 이름)이 보이는지 검증. */
  async expectTabPanelVisible(
    tabName: string | RegExp,
    opts?: { within?: Locator }
  ): Promise<void> {
    const root = opts?.within ?? this.page
    await expect(root.getByRole("tabpanel", { name: tabName })).toBeVisible()
  }

  /** 경로로 진입하고, 화면이 조작 가능해질 때까지(하이드레이션) 기다린다. */
  async open(path: string): Promise<void> {
    await this.page.goto(path)
    await this.waitForHydration()
  }

  /** 현재 URL 그대로 새로고침 — 저장된 상태가 살아남는지 볼 때. */
  async reload(): Promise<void> {
    await this.page.reload()
    await this.waitForHydration()
  }

  /**
   * 서버가 그린 HTML 은 React 가 붙기 전에도 보이고 클릭된다. `goto` 가 기다리는
   * `load` 시점에도 하이드레이션이 안 끝난 경우가 흔하다(실측: 홈 4/5, CPU 4배
   * 감속 시 5/5). React 는 그 사이의 클릭을 대개 하이드레이션 뒤 재생해 주지만
   * 모든 입력을 재생하지는 않으므로, 조작 전에 하이드레이션을 기다린다.
   * React 는 하이드레이션한 요소에 `__reactProps$…` 키를 단다 — main 에 그 키가
   * 생기면 조작해도 된다. React 내부 키에 기대므로 React 메이저 업그레이드 때
   * 이 대기가 끝나지 않으면 여기부터 볼 것.
   */
  async waitForHydration(): Promise<void> {
    await this.page.waitForFunction(() => {
      const main = document.querySelector("main")
      return (
        main !== null &&
        Object.keys(main).some((key) => key.startsWith("__reactProps$"))
      )
    })
  }
}
